{
  "name": "Phidget热电偶温度传感器",
  "name_en": "Phidget Thermocouple Sensor",
  "manufacturer": "Phidgets",
  "description": "用于通过热电偶测量温度的传感器设备，可用于实验装置、样品或环境的温度采集与连续监测。",
  "description_en": "A thermocouple-based temperature sensing device used to measure and continuously monitor the temperature of experimental setups, samples, or the environment.",
  "tag_hints": [
    "thermocouple temperature sensing",
    "temperature monitoring",
    "Phidgets",
    "sensor readout",
    "lab instrumentation"
  ],
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接热电偶温度传感器并等待设备就绪。",
      "description_en": "Connect to the thermocouple temperature sensor and wait for the device to become ready."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开与热电偶温度传感器的连接。",
      "description_en": "Disconnect from the thermocouple temperature sensor."
    },
    {
      "action_name": "auto-rcv_vals",
      "description": "读取温度测量值。",
      "description_en": "Read the measured temperature value."
    }
  ]
}

